 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Collect contiguous sequences along either horizontal boundary. Interior
    # singleton markers are replaced by the boundary sequence containing them.
    patterns = []
    for edge in (g[0], g[-1]):
        c = 0
        while c < w:
            if edge[c] == 0:
                c += 1
                continue
            start = c
            while c < w and edge[c] != 0:
                c += 1
            patterns.append(edge[start:c])
    for r in range(1, h - 1):
        for c in range(w):
            value = g[r][c]
            if value == 0:
                continue
            for seq in patterns:
                if value in seq:
                    left = c - seq.index(value)
                    for i, color in enumerate(seq):
                        x = left + i
                        if 0 <= x < w:
                            g[r][x] = color
                    break
    return g
